// eslint-disable-next-line camelcase
export function block_keys(e: any) {
    switch (e.keyCode) {
        case 37:
        case 39:
        case 38:
        case 40:
            e.preventDefault();
            break; // Space
        default:
            break; // do not block other keys
    }
}

export function showHideTilesInspector(show: boolean) {
    if (show) {
        jQuery(".cesium-viewer-cesium3DTilesInspectorContainer").show();
    } else {
        jQuery(".cesium-viewer-cesium3DTilesInspectorContainer").hide();
    }
}

export function disableDefaultScreenSpaceCameraController(scene: Scene) {
    // disable the default event handlers

    scene.screenSpaceCameraController.enableRotate = false;
    scene.screenSpaceCameraController.enableTranslate = false;
    scene.screenSpaceCameraController.enableZoom = false;
    scene.screenSpaceCameraController.enableTilt = false;
    scene.screenSpaceCameraController.enableLook = false;
}

export function enableDefaultScreenSpaceCameraController(scene: Scene) {
    // enable the default event handlers

    scene.screenSpaceCameraController.enableRotate = true;
    scene.screenSpaceCameraController.enableTranslate = true;
    scene.screenSpaceCameraController.enableZoom = true;
    scene.screenSpaceCameraController.enableTilt = true;
    scene.screenSpaceCameraController.enableLook = true;
}

export function flyToTileset(options: {
    viewer: Viewer;
    tileset: Cesium3DTileset;
    defaultCameraPositionDirection: RelativeCameraPositionOrientation | CameraPositionOrientation | undefined;
    complete?: () => void;
}) {
    const viewer = options.viewer;
    const camera = viewer.camera;
    const tileset = options.tileset;
    const defaultCameraPositionDirection = options.defaultCameraPositionDirection;

    const cameraPositionOrientation = defaultCameraPositionDirection as CameraPositionOrientation;
    const relativeCameraPositionOrientation = defaultCameraPositionDirection as RelativeCameraPositionOrientation;

    if (relativeCameraPositionOrientation && relativeCameraPositionOrientation.offsetX !== undefined) {
        // old style
        const offset = new Cartesian3(
            relativeCameraPositionOrientation.offsetX,
            relativeCameraPositionOrientation.offsetY,
            relativeCameraPositionOrientation.offsetZ
        );

        const destination = Cartesian3.add(tileset.boundingSphere.center, offset, new Cartesian3());

        // Set camera mode before flying
        if (relativeCameraPositionOrientation.view_mode === "orthographic") {
            const currentFrustum = camera.frustum;
            const width = currentFrustum instanceof OrthographicFrustum ? currentFrustum.width : 100;
            const aspectRatio =
                camera.frustum instanceof OrthographicFrustum || camera.frustum instanceof PerspectiveFrustum
                    ? camera.frustum.aspectRatio
                    : undefined;
            camera.frustum = new OrthographicFrustum({
                width: width,
                aspectRatio: aspectRatio || 1.0
            });
        } else {
            const fov = relativeCameraPositionOrientation.field_of_view
                ? CesiumMath.toRadians(relativeCameraPositionOrientation.field_of_view)
                : CesiumMath.toRadians(60);
            const aspectRatio =
                camera.frustum instanceof OrthographicFrustum || camera.frustum instanceof PerspectiveFrustum
                    ? camera.frustum.aspectRatio
                    : undefined;
            camera.frustum = new PerspectiveFrustum({
                fov: fov,
                aspectRatio: aspectRatio || 1.0
            });
        }

        viewer.camera.flyTo({
            destination: destination,
            orientation: {
                heading: CesiumMath.toRadians(relativeCameraPositionOrientation.heading),
                pitch: CesiumMath.toRadians(relativeCameraPositionOrientation.pitch),
                roll: CesiumMath.toRadians(relativeCameraPositionOrientation.roll)
            },
            complete: options.complete
        });
    } else if (cameraPositionOrientation && cameraPositionOrientation.longitude !== undefined) {
        const destination = Cartesian3.fromDegrees(
            cameraPositionOrientation.longitude,
            cameraPositionOrientation.latitude,
            cameraPositionOrientation.height
        );

        // Set camera mode before flying
        if (cameraPositionOrientation.view_mode === "orthographic") {
            const currentFrustum = camera.frustum;
            const width = currentFrustum instanceof OrthographicFrustum ? currentFrustum.width : 100;
            const aspectRatio =
                camera.frustum instanceof OrthographicFrustum || camera.frustum instanceof PerspectiveFrustum
                    ? camera.frustum.aspectRatio
                    : undefined;
            camera.frustum = new OrthographicFrustum({
                width: width,
                aspectRatio: aspectRatio || 1.0
            });
        } else {
            const fov = cameraPositionOrientation.field_of_view
                ? CesiumMath.toRadians(cameraPositionOrientation.field_of_view)
                : CesiumMath.toRadians(60);
            const aspectRatio =
                camera.frustum instanceof OrthographicFrustum || camera.frustum instanceof PerspectiveFrustum
                    ? camera.frustum.aspectRatio
                    : undefined;
            camera.frustum = new PerspectiveFrustum({
                fov: fov,
                aspectRatio: aspectRatio || 1.0
            });
        }

        viewer.camera.flyTo({
            destination: destination,
            orientation: {
                heading: CesiumMath.toRadians(cameraPositionOrientation.heading),
                pitch: CesiumMath.toRadians(cameraPositionOrientation.pitch),
                roll: CesiumMath.toRadians(cameraPositionOrientation.roll)
            },
            complete: options.complete
        });
    } else {
        const boundingSphere = calculateTightBoundinSphere(tileset);

        camera.flyToBoundingSphere(boundingSphere, {
            complete: options.complete
        });
    }
}

// http://jsfiddle.net/LYteC/4/

export const decodeEntities = (function () {
    // this prevents any overhead from creating the object each time
    const element = document.createElement("div");

    function decodeHTMLEntities(str: any) {
        if (str && typeof str === "string") {
            // strip script/html tags
            // eslint-disable-next-line no-param-reassign
            str = str.replace(/<script[^>]*>([\S\s]*?)<\/script>/gim, "");
            // eslint-disable-next-line no-param-reassign
            str = str.replace(/<\/?\w(?:[^"'>]|"[^"]*"|'[^']*')*>/gim, "");
            element.innerHTML = str;
            // eslint-disable-next-line no-param-reassign
            str = element.textContent;
            element.textContent = "";
        }

        return str;
    }

    return decodeHTMLEntities;
})();

export function getTiesetURL(tilesetServer: string, postSlug: string, newStyleURL: boolean) {
    const oldTilesetURL = `${tilesetServer}/${postSlug}/tileset.json`;
    const newTilesetURL = `${tilesetServer}/${postSlug}/tileset/tileset.json`;

    if (newStyleURL) {
        return newTilesetURL;
    }

    return oldTilesetURL;
}

export function existUrl(url: string) {
    const request = new XMLHttpRequest();

    request.open("GET", url, false);
    request.send(); // there will be a 'pause' here until the response to come.
    // the object request will be actually modified
    if (request.status === 404) {
        return false;
    }

    return true;
}
